// The unlock table as data (contracts §3.2) plus "is this usable in that session?" (contracts §3.1).
// Data: unlocks.data.ts, generated by gen-unlocks.ts from docs/design/contracts.md. This file is the API.
//
//   bun spikes/content-draft/tools/unlocks.ts U03.L02          what a lesson may use, and what it unlocks
//   bun spikes/content-draft/tools/unlocks.ts swingBy rhodes   where a name unlocks
import { DEFAULT_ORDER, LESSONS, UNLOCK_ROWS } from "./unlocks.data.ts";

export { DEFAULT_ORDER, LESSONS, UNLOCK_ROWS };

export interface UnlockGates {
  /** Callee or method names. */
  fn?: string[];
  /** Mini-notation operators, by the names in MINI_OPS. */
  mini?: string[];
  /** Sound names inside s("…"). */
  sound?: string[];
  /** .bank("…") values. */
  bank?: string[];
  /** Scale names after the tonic: "major", "harmonic:minor". */
  scale?: string[];
  /** Chord-symbol suffixes (symbol minus root): "" "m" "^7". */
  chord?: string[];
  /** .dict("…") values. */
  dict?: string[];
  /** Bare identifiers that are not calls: sine, saw, perlin, silence. */
  ident?: string[];
  /** Structural usages; see SPECIAL. */
  special?: string[];
  /** Not visible in code (app features, lenses, templates). */
  none?: true;
}
export interface UnlockRow {
  /** tb.* | snd.* | scale.* | chord.* (contracts §1.2). */
  id: string;
  kind: "tool" | "sound" | "scale" | "chord" | "feature" | "lens" | "template";
  /** Table group A to H of contracts §3.2. */
  group: string;
  /** The "Code form" cell, verbatim. */
  code: string;
  /** Alternative unlock sites (rule 11). `start` = START rows (granted when the session starts). */
  sites: { at: string; when: "complete" | "start" }[];
  /** Rule 12: granted silently when this lesson is completed if the START site has not happened. */
  fallbackAt?: string;
  /** Rows marked `*`: behind the voicing gate (rule 6). */
  voicingGate?: true;
  /** Rows marked †: audibility pending spike S3 (rule 7). */
  audibilityPending?: true;
  concept: string;
  /** The "Preview before unlock" cell, verbatim; null = no planned preview. */
  preview: string | null;
  notes?: string;
  gates: UnlockGates;
}

/** The checker's names for mini-notation operators, and the row that gates each. */
export const MINI_OPS = {
  seq: "two or more space-separated steps",
  "*": "x*n repeat",
  "~": "rest",
  "[]": "[a b] subdivision",
  "@": "x@n elongate",
  _: "_ hold",
  "!": "x!n replicate",
  "<>": "<a b> one per bar",
  ",": "a, b stack",
  "?": "x? maybe",
  "..": "a .. b range",
  "{}": "{a b c}%n polymeter",
  "(k,n)": "x(k,n) euclid",
  "(k,n,r)": "x(k,n,r) euclid with rotation",
} as const;
/** Mini operators that exist in Strudel but have no row in the unlock table: never used in content. */
export const MINI_UNCATALOGUED = { "/": "x/n slow", "|": "a|b random choice", ".": "a . b feet", ":": "x:n sample index" } as const;

/** Structural usages (the `special` gate). */
export const SPECIAL = {
  label: "a lowercase track label `name:`",
  "label-mute": "`_name:` code mute",
  const: "`const name = …`",
  "note-names": "letter names inside note(\"…\")",
  "note-accidentals": "# or b inside a note name",
  "note-midi": "numbers inside note(…)",
  "s-on-pitched": ".s(\"…\") as a method on a pitched pattern",
  "n-range": "negative or >= 7 values inside n(\"…\")",
  "n-chromatic": "chromatic steps inside n(\"…\"): 3# 6b",
  "scale-patterned": "a patterned .scale(\"<…>\")",
  "transpose-interval": "an interval string in .transpose(\"3M\")",
  "chord-as-method": "n(\"…\").chord(…).voicing(): single voices of a voicing",
  "swing-patterned": "a patterned swing amount: .swingBy(\"<0 .1>\", 4)",
  "mode:below": ".mode(\"below\")",
  "mode:root": ".mode(\"root:g2\")",
  "mode:duck": ".mode(\"duck\")",
} as const;

// --- lookups ------------------------------------------------------------------------------------

function index(pick: (g: UnlockGates) => string[] | undefined): Map<string, UnlockRow> {
  const map = new Map<string, UnlockRow>();
  for (const row of UNLOCK_ROWS) for (const name of pick(row.gates) ?? []) map.set(name, row);
  return map;
}
export const BY_ID = new Map(UNLOCK_ROWS.map((r) => [r.id, r]));
export const BY_FN = index((g) => g.fn);
export const BY_MINI = index((g) => g.mini);
export const BY_SOUND = index((g) => g.sound);
export const BY_BANK = index((g) => g.bank);
export const BY_SCALE = index((g) => g.scale);
export const BY_CHORD = index((g) => g.chord);
export const BY_DICT = index((g) => g.dict);
export const BY_IDENT = index((g) => g.ident);
export const BY_SPECIAL = index((g) => g.special);

export const DRUM_SOUNDS = new Set(
  UNLOCK_ROWS.filter((r) => r.id.startsWith("snd.drum.")).flatMap((r) => r.gates.sound ?? []),
);
export const PITCHED_SOUNDS = new Set(
  UNLOCK_ROWS.filter((r) => r.group === "G" && r.kind === "sound").flatMap((r) => r.gates.sound ?? []),
);

// --- session order (contracts §2.3 to §2.6, §3.1 rules 2, 10, 11, 12, §7.6) -----------------------

const CORE_LESSONS = LESSONS.map((l) => l.id).filter((id) => id.startsWith("U"));
const coreIndex = (id: string): number => CORE_LESSONS.indexOf(id);
const lastLessonOf = (unit: string): string =>
  CORE_LESSONS.filter((id) => id.startsWith(`${unit}.`)).at(-1) ?? `${unit}.L01`;
const trackLessons = (letter: string): string[] =>
  LESSONS.map((l) => l.id).filter((id) => id.startsWith(letter) && /^[JRA]\d\./.test(id));

/** The last core lesson guaranteed complete when a capstone opens (contracts §2.4 "Opens after"). */
const CAPSTONE_AFTER: Record<string, string> = {
  C0: lastLessonOf("U01"),
  C1: lastLessonOf("U02"),
  C2: lastLessonOf("U07"),
  X1: lastLessonOf("U07"),
  C3: lastLessonOf("U09"),
  C4: lastLessonOf("U10"),
  C5: lastLessonOf("U11"),
  X2: lastLessonOf("U11"),
  C6: lastLessonOf("U14"),
  C7: lastLessonOf("U17"),
  "CF-A": lastLessonOf("U17"),
  "CF-T": lastLessonOf("U14"),
};
/** The last core lesson guaranteed complete when a track lesson opens (contracts §2.6 gates). */
function trackGate(lesson: string): string {
  if (lesson === "J2.L04") return lastLessonOf("U14");
  if (/^J[123]\./.test(lesson)) return lastLessonOf("U13");
  if (lesson.startsWith("J4.")) return lastLessonOf("U15");
  if (lesson.startsWith("J5.")) return lastLessonOf("U17");
  if (lesson.startsWith("R")) return lastLessonOf("U13");
  if (/^A1\.L0[1-4]$/.test(lesson)) return "U03.L02";
  if (lesson.startsWith("A1.")) return lastLessonOf("U09");
  return lastLessonOf("U10");
}

export function isKnownSession(session: string): boolean {
  return (
    LESSONS.some((l) => l.id === session) ||
    DEFAULT_ORDER.includes(session) ||
    /^(?:U\d{2}\.CP|J\.CP[12]|R\.CP|A\.CP|(?:JC[1-4]|RC[12]|AC[12])\.S\d)$/.test(session)
  );
}

/** Core lessons that are complete in EVERY legal order when `session` starts, as an index bound. */
function coreBound(session: string): number {
  if (coreIndex(session) >= 0) return coreIndex(session) - 1;
  const cp = /^(U\d{2})\.CP$/.exec(session);
  if (cp) return coreIndex(lastLessonOf(cp[1] as string));
  const cap = /^(C[0-7]|X[12]|CF-A|CF-T)\.S\d$/.exec(session);
  if (cap) return coreIndex(CAPSTONE_AFTER[cap[1] as string] as string);
  if (/^[JRA]\d\.L\d{2}$/.test(session)) return coreIndex(trackGate(session));
  // Track checkpoints and track capstones: the whole gate of the track's last lesson (approximate).
  if (/^(?:J\.CP1|JC1\.)/.test(session)) return coreIndex(lastLessonOf("U13"));
  if (/^(?:J\.CP2|JC[234]\.)/.test(session)) return coreIndex(lastLessonOf("U17"));
  if (/^(?:R\.CP|RC[12]\.)/.test(session)) return coreIndex(lastLessonOf("U13"));
  if (/^(?:A\.CP|AC1\.)/.test(session)) return coreIndex(lastLessonOf("U11"));
  if (session.startsWith("AC2.")) return coreIndex(lastLessonOf("U13"));
  return -1;
}

/** True when `site` is complete (or started) before `session` in every legal order. */
export function guaranteedBefore(site: string, session: string): boolean {
  if (site === session) return false;
  if (coreIndex(site) >= 0) return coreIndex(site) <= coreBound(session);
  // A track lesson precedes only later lessons, checkpoints and capstones of its own track; J2.L04 can be
  // passed over, so nothing may rely on it.
  if (/^[JRA]\d\.L\d{2}$/.test(site)) {
    if (site === "J2.L04") return false;
    const letter = site[0] as string;
    const order = trackLessons(letter);
    if (/^[JRA]\d\.L\d{2}$/.test(session) && session[0] === letter)
      return order.indexOf(site) < order.indexOf(session);
    if (letter === "J" && /^(?:J\.CP1|JC1\.)/.test(session))
      return order.indexOf(site) <= order.indexOf("J2.L03");
    if (letter === "J" && /^(?:J\.CP2|JC[234]\.)/.test(session)) return true;
    if (letter === "R" && /^(?:R\.CP|RC[12]\.)/.test(session)) return true;
    if (letter === "A" && /^(?:A\.CP|AC[12]\.)/.test(session)) return true;
    if (session.startsWith("AC2.") && (site <= "J3.L04" || site <= "R1.L05"))
      return (letter === "J" && order.indexOf(site) <= order.indexOf("J3.L04")) ||
        (letter === "R" && order.indexOf(site) <= order.indexOf("R1.L05"));
    return false;
  }
  // A capstone never gates anything (contracts §2.4): a capstone site counts only inside that capstone.
  const capSite = /^(.+)\.S(\d)$/.exec(site);
  const capSession = /^(.+)\.S(\d)$/.exec(session);
  if (capSite && capSession && capSite[1] === capSession[1]) return Number(capSite[2]) < Number(capSession[2]);
  return false;
}

export interface Usable {
  ok: boolean;
  /** `own` = this session teaches it (usable from its first step, rule 2). */
  via?: "own" | "earlier" | "fallback";
  site?: string;
  /** For the report: where it unlocks. */
  unlocksAt: string;
}
/** Whether a row may be used in learner-facing code of `session` (contracts §3.1 rules 2, 10, 11, 12). */
export function usableIn(row: UnlockRow, session: string): Usable {
  const unlocksAt =
    row.sites.map((s) => (s.when === "start" ? `${s.at} (START)` : s.at)).join(" or ") +
    (row.fallbackAt ? `; fallback after ${row.fallbackAt}` : "") +
    (row.voicingGate ? " (voicing gate)" : "");
  for (const s of row.sites) if (s.at === session) return { ok: true, via: "own", site: s.at, unlocksAt };
  for (const s of row.sites)
    if (guaranteedBefore(s.at, session)) return { ok: true, via: "earlier", site: s.at, unlocksAt };
  if (row.fallbackAt && guaranteedBefore(row.fallbackAt, session))
    return { ok: true, via: "fallback", site: row.fallbackAt, unlocksAt };
  return { ok: false, unlocksAt };
}
/** Every row usable in `session`. */
export function unlockedIn(session: string): UnlockRow[] {
  return UNLOCK_ROWS.filter((r) => usableIn(r, session).ok);
}
/** Rows whose unlock site is `session` itself: what the lesson teaches. */
export function unlocksOf(session: string): UnlockRow[] {
  return UNLOCK_ROWS.filter((r) => r.sites.some((s) => s.at === session));
}
/** True when the row's "Preview before unlock" cell names this lesson (U00.L01, "U01.L09 listen step"). */
export function previewPlannedIn(row: UnlockRow, session: string): boolean {
  return row.preview?.includes(session) ?? false;
}

// --- chord symbols (STYLE §5.1, §5.2; contracts §0.1, §0.2, §0.13, §0.14) --------------------------

export const DICTS = ["ireal", "ireal-ext", "triads", "lefthand", "guidetones"] as const;
export type Dict = (typeof DICTS)[number];
/** STYLE §5.2, transcribed: ok = sounds with the right notes, silent = "—", wrong = "✗". */
type Cell = "ok" | "silent" | "wrong";
const row5 = (a: Cell, b: Cell, c: Cell, d: Cell, e: Cell): Record<Dict, Cell> => ({
  ireal: a,
  "ireal-ext": b,
  triads: c,
  lefthand: d,
  guidetones: e,
});
export const CHORD_DICT_TABLE: Record<string, Record<Dict, Cell>> = {
  "": row5("ok", "ok", "ok", "silent", "silent"),
  m: row5("ok", "ok", "ok", "silent", "silent"),
  o: row5("ok", "ok", "ok", "silent", "silent"),
  aug: row5("ok", "ok", "wrong", "silent", "silent"),
  "^7": row5("ok", "ok", "silent", "ok", "ok"),
  "7": row5("ok", "ok", "silent", "ok", "ok"),
  m7: row5("ok", "ok", "silent", "ok", "ok"),
  m7b5: row5("ok", "ok", "silent", "ok", "ok"),
  o7: row5("ok", "ok", "silent", "ok", "ok"),
  m6: row5("ok", "ok", "silent", "ok", "ok"),
  "69": row5("ok", "ok", "silent", "wrong", "ok"),
  "6": row5("ok", "ok", "silent", "silent", "ok"),
  "7b9": row5("ok", "ok", "silent", "ok", "ok"),
  "7#9": row5("ok", "ok", "silent", "ok", "ok"),
  "7#11": row5("ok", "ok", "silent", "ok", "ok"),
  "7b13": row5("ok", "ok", "silent", "ok", "ok"),
  "^9": row5("ok", "ok", "silent", "silent", "ok"),
  m9: row5("ok", "ok", "silent", "silent", "ok"),
  "9": row5("ok", "ok", "silent", "silent", "silent"),
  "13": row5("ok", "ok", "silent", "silent", "silent"),
  m11: row5("ok", "ok", "silent", "silent", "silent"),
  "7alt": row5("ok", "ok", "silent", "silent", "silent"),
  sus: row5("ok", "ok", "silent", "silent", "silent"),
  "7sus": row5("ok", "ok", "silent", "silent", "silent"),
  "2": row5("ok", "ok", "silent", "silent", "silent"),
  add9: row5("ok", "ok", "silent", "silent", "silent"),
  "^7#11": row5("ok", "ok", "silent", "silent", "silent"),
  "m^7": row5("ok", "ok", "silent", "silent", "silent"),
  mM7: row5("silent", "silent", "silent", "ok", "ok"),
};
/** Spellings that are never written in authored code (STYLE §5.1), with the canonical one. */
export const FORBIDDEN_CHORD_SUFFIX: Record<string, string> = {
  maj7: "^7",
  M7: "^7",
  M: "",
  maj: "",
  dim: "o",
  dim7: "o7",
  sus4: "sus",
  sus2: "2",
  maj9: "^9",
  "-": "m",
  "-7": "m7",
  h7: "m7b5",
  h: "m7b5",
  "+": "aug",
  min: "m",
  min7: "m7",
  "-^7": "m^7",
};
export interface ChordCheck {
  ok: boolean;
  /** Feedback-style code: code.unknown-chord, code.lowercase-chord-root, code.chord-not-in-dict. */
  code?: string;
  message?: string;
  root?: string;
  suffix?: string;
  family?: UnlockRow;
}
/** Checks one chord symbol against the dictionary of its chain (default `ireal`). */
export function checkChordSymbol(symbol: string, dict: string = "ireal"): ChordCheck {
  if (/^[a-g]/.test(symbol))
    return {
      ok: false,
      code: "code.lowercase-chord-root",
      message: `"${symbol}": chord roots are capitals ("${symbol[0]?.toUpperCase()}${symbol.slice(1)}"); a lowercase root is silent`,
    };
  const m = /^([A-G][#b]?)(.*)$/.exec(symbol);
  if (!m) return { ok: false, code: "code.unknown-chord", message: `"${symbol}" is not a chord symbol` };
  const [, root, suffix] = m as unknown as [string, string, string];
  if (suffix in FORBIDDEN_CHORD_SUFFIX)
    return {
      ok: false,
      code: "code.unknown-chord",
      root,
      suffix,
      message: `"${symbol}" is not an Oak spelling: write "${root}${FORBIDDEN_CHORD_SUFFIX[suffix]}" (STYLE §5.1)`,
    };
  const cells = CHORD_DICT_TABLE[suffix];
  const family = BY_CHORD.get(suffix);
  if (!cells)
    return {
      ok: false,
      code: "code.unknown-chord",
      root,
      suffix,
      message: `"${symbol}": suffix "${suffix}" is not in the STYLE §5 chord table`,
    };
  if (!(DICTS as readonly string[]).includes(dict))
    return { ok: false, code: "code.chord-not-in-dict", root, suffix, message: `unknown dictionary "${dict}"` };
  const cell = cells[dict as Dict];
  if (cell !== "ok") {
    const good = DICTS.filter((d) => cells[d] === "ok").join(", ");
    return {
      ok: false,
      code: "code.chord-not-in-dict",
      root,
      suffix,
      ...(family ? { family } : {}),
      message:
        cell === "silent"
          ? `"${symbol}" is SILENT in dict "${dict}" (it resolves in: ${good})`
          : `"${symbol}" sounds with WRONG notes in dict "${dict}" (Strudel 1.2.6 bug; use: ${good}, or voice it by hand)`,
    };
  }
  return { ok: true, root, suffix, ...(family ? { family } : {}) };
}

// --- CLI ----------------------------------------------------------------------------------------

if (import.meta.main) {
  const args = process.argv.slice(2);
  if (args.length === 0) {
    console.log("usage: bun spikes/content-draft/tools/unlocks.ts <session id | name> …");
    process.exit(2);
  }
  for (const arg of args) {
    if (isKnownSession(arg)) {
      const own = unlocksOf(arg);
      const all = unlockedIn(arg).filter((r) => !r.gates.none);
      console.log(`\n${arg}: teaches ${own.length ? own.map((r) => r.id).join(" ") : "(nothing new)"}`);
      for (const group of "BCDEFGH") {
        const rows = all.filter((r) => r.group === group);
        if (rows.length) console.log(`  ${group}: ${rows.map((r) => r.id.replace(/^tb\./, "")).join(" ")}`);
      }
      const next = UNLOCK_ROWS.filter((r) => !r.gates.none && !usableIn(r, arg).ok && previewPlannedIn(r, arg));
      if (next.length) console.log(`  planned previews here (read-only): ${next.map((r) => r.id).join(" ")}`);
      continue;
    }
    const hits = UNLOCK_ROWS.filter(
      (r) => r.id === arg || r.id.endsWith(`.${arg}`) || Object.values(r.gates).flat().includes(arg),
    );
    if (hits.length === 0) console.log(`${arg}: no row in contracts §3.2 (never used in content)`);
    for (const r of hits)
      console.log(`${arg}: ${r.id}  ${r.code}  unlocks at ${usableIn(r, "").unlocksAt}${r.preview ? `  preview: ${r.preview}` : ""}`);
  }
}
